/bin/bash -lc "node --input-type=module - <<'EOF'
import { chunk, parseDate, formatMoney, retry } from './src/util.js';
console.log('chunk-zero-start');
try { console.log(chunk([1], 0)); } catch (e) { console.log('chunk-zero-error', e?.message ?? String(e)); }
EOF"

/bin/bash -lc "timeout 1s node --input-type=module -e \"import('./src/util.js').then(({chunk}) => console.log(chunk([1], 0)))\"; printf 'exit=%s\\n' \""'$?"; node --input-type=module - <<'"'EOF'
import { parseDate, formatMoney, retry } from './src/util.js';
console.log('parseDate-invalid', parseDate('2026-02-30'));
console.log('formatMoney-negative', formatMoney(-1));
try { retry(() => { throw new Error('x'); }, 0); } catch (e) { console.log('retry-zero', e === undefined ? 'undefined thrown' : e.message); }
EOF"

